W += [
E('saint','/seɪnt/；人名前常弱读 /sənt/','圣徒；圣人；极有耐心、善良的人','宗教中受尊崇的人；日常夸张地说某人好得让人感激。','拉丁 sanctus 神圣的，经古英语 sanct 与法语 saint 两线汇合；不能把英语 saint 当成 sanctify 的缩写。',SAINT,'Saint 放在人名前可缩写 St；宗教中的具体认定随传统而异。You are a saint! 在日常可以只是感谢对方极耐心、乐于帮忙。','a patron saint；Saint Peter；You are a saint!。','saint 是人或称号，holy 是神圣的。no saint 常承认一个人也有缺点，并非指教会正式取消头衔。',('The church is named after a local saint.','这座教堂以当地一位圣徒的名字命名。'),('You are a saint for helping me move all these boxes.','你帮我搬这么多箱子，真是太好心了。'),sources=['https://www.etymonline.com/word/saint','https://www.oxfordlearnersdictionaries.com/definition/english/saint']),
E('saintly','/ˈseɪntli/','圣人般的；极善良、极有耐心的','把一个人的善良或耐心夸到近乎圣人的程度。','saint + -ly；这里 -ly 构成形容词，不是普通的方式副词。',SAINT+[['英语 saint + -ly → saintly','圣人 → 像圣人一样的']],'saintly patience 是极大的耐心；a saintly expression 是看起来圣洁的神情。语境也可能带打趣，不一定是在作宗教评价。','saintly patience；a saintly person；a saintly expression。','saintly 可以真心赞扬；sanctimonious 常批评摆出道德优越的样子，语气完全不同。',('She showed saintly patience with the endless questions.','面对没完没了的问题，她表现出圣人般的耐心。'),('His friends described him as kind, though hardly saintly.','朋友们说他善良，但远没有到圣人般的地步。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/saintly','https://en.wiktionary.org/wiki/saintly#English']),
E('sanctuary','英 /ˈsæŋktʃuəri/；美 /ˈsæŋktʃueri/','庇护所；避难；保护区；圣所','一个被划出来、让人或动物免受侵扰的安全地方。','拉丁 sanctus → sanctuarium，经法语 saintuaire 借入；原来的圣所保护传统促成避难、庇护义。',SAN+[['后期拉丁 sanctuarium → 古法语 saintuaire → 英语 sanctuary','圣所、神圣地点'],['英语 sanctuary 的扩展','可寻求庇护之地 → 一般避难处、动物保护区']],'seek sanctuary 是寻求庇护；a bird sanctuary 是鸟类保护区。也可把家里安静的房间称为 a sanctuary，强调终于能歇下来。','seek sanctuary；a wildlife sanctuary；a sanctuary from noise。','shelter 可以是一处遮风挡雨的地方；sanctuary 更强调受到保护、免受侵扰。',('The wetland is a sanctuary for migrating birds.','这片湿地是候鸟的保护区。'),('For her, the small garden was a sanctuary from the busy city.','对她来说，那座小花园是远离城市喧闹的安静避所。'),sources=['https://www.etymonline.com/word/sanctuary','https://www.oxfordlearnersdictionaries.com/definition/english/sanctuary']),
E('sanction','/ˈsæŋkʃən/','正式批准；认可；制裁、处罚','权威为规则撑腰：允许的就批准，违反的就处罚。','来自拉丁 sanctio 法令、确认行为，经法语或直接借入；英语动词由名词发展，两支现代义都连着规则和权威。',SANCTION,'with official sanction 是获得正式许可；impose sanctions on 是对……施加制裁。动词 sanction a plan 多是批准计划，sanction a firm for misconduct 则可能是因违规处罚公司。','official sanction；sanction a proposal；impose/lift sanctions；sanctions against。','不要固定翻成批准或制裁。看宾语、for 后的原因，以及 impose、lift 等搭配，才能确定方向。',('The board sanctioned the revised plan.','董事会批准了修改后的计划。'),('The league imposed sanctions on the club for breaking the rules.','联盟因该俱乐部违反规则而对其作出处罚。'),('The event went ahead without official sanction.','活动未经正式批准就举行了。'),sources=['https://www.etymonline.com/word/sanction','https://www.oxfordlearnersdictionaries.com/definition/english/sanction_1','https://www.oxfordlearnersdictionaries.com/definition/english/sanction_2']),
E('sanctioned','/ˈsæŋkʃənd/','获得正式批准的；受到制裁或处罚的','同样一个词形，可能拿到许可，也可能收到罚单。','sanction + -ed；过去分词兼作形容词，保留动词的批准和处罚两支。',SANCTION+[['英语 sanction + -ed → sanctioned','已获批准；或已受处罚，依上下文判断']],'a sanctioned event 通常是得到批准的活动；a sanctioned company 在制裁报道里可能是受限制的公司。for violating the rules 这类原因常把意思引向处罚。','an officially sanctioned event；a sanctioned company；sanctioned for misconduct。','authorized 只有获授权方向，penalized 只有受罚方向；sanctioned 必须结合语境读。',('The race was an officially sanctioned event.','这场比赛是正式批准举办的赛事。'),('The athlete was sanctioned for violating the competition rules.','这名运动员因违反竞赛规则受到处罚。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/sanction_2','https://www.etymonline.com/word/sanction']),
E('unsanctioned','英 /ʌnˈsæŋkʃənd/','未经批准的；未获认可的','事情做了或正在做，但没有拿到相关机构的许可。','un- 不 + sanctioned；常用的是批准一支的否定。',SANCTION+[['英语 sanctioned〔获批准〕+ un- → unsanctioned','未经正式认可、批准的']],'an unsanctioned event 是未获批准的活动；unsanctioned software 是组织没有认可的软件。通常不是说从未被处罚，不能只把所有 sanctioned 的意思逐一反过来。','an unsanctioned event；unsanctioned changes；unsanctioned software。','unofficial 说不是官方性质；unsanctioned 更突出缺少许可或认可，两者不总相同。',('The review found several unsanctioned changes to the design.','审查发现设计中有几处未经批准的修改。'),('Employees were asked to remove unsanctioned software from office computers.','员工被要求从办公电脑上移除未经认可的软件。'),sources=['https://www.collinsdictionary.com/dictionary/english/unsanctioned','https://en.wiktionary.org/wiki/unsanctioned#English']),
E('sacrosanct','英 /ˈsækrəʊsæŋkt/；美 /ˈsækroʊsæŋkt/','神圣不可侵犯的；不容改变或质疑的','像在某件事周围画出一圈：这件事不能随便碰。','拉丁 sacrosanctus；sacro 接神圣仪式，sanctus 接使神圣、确认，原指受神圣约束保护。',SAN+[['拉丁 sacro + sanctus → sacrosanctus → 英语 sacrosanct','由宗教仪式确认、保护 → 不可侵犯']],'treat a rule as sacrosanct 是把规则当成不可质疑；也可幽默地说某人的午休不可打扰。常见于原则、权利、习惯，不局限宗教。','regard as sacrosanct；treat as sacrosanct；nothing is sacrosanct。','important 只是重要；sacrosanct 还带别人不能改、不能碰的强硬边界。',('The committee treats the privacy of participants as sacrosanct.','委员会把参与者的隐私看作不可侵犯。'),('For him, Sunday breakfast with the family is sacrosanct.','对他来说，星期天与家人共进早餐这件事不容打扰。'),sources=['https://www.etymonline.com/word/sacrosanct','https://en.wiktionary.org/wiki/sacrosanct#English','https://www.oxfordlearnersdictionaries.com/definition/english/sacrosanct']),
E('sanctity','/ˈsæŋktəti/','神圣性；不可侵犯性','某件事受到很高的敬重，人们认为不该轻易破坏它。','拉丁 sanctitas，经古法语 sanctete 等形式借入；与 sanctus 同源，不是英语 saint 直接拼出这个词。',SAN+[['拉丁 sanctitas → 古法语 sanctete → 英语 sanctity','神圣、圣洁的性质；后也说不可侵犯性']],'the sanctity of life 是生命的神圣性；the sanctity of the home 强调私人居所受到尊重。词本身有价值立场，语气比 importance 更庄重。','the sanctity of life；respect the sanctity of；preserve the sanctity of。','sanity 是神志清醒；sanctity 是神圣性。少了几个字母，来源和意思都不同。',('The essay explores the idea of the sanctity of human life.','文章探讨人的生命具有神圣性这一观念。'),('The ceremony emphasizes the sanctity of the site.','仪式强调这个地点的神圣性。'),sources=['https://www.etymonline.com/word/sanctity','https://www.oxfordlearnersdictionaries.com/definition/english/sanctity']),
E('sanctify','/ˈsæŋktɪfaɪ/','使神圣；祝圣；赋予神圣或正当色彩','把某物从普通用途里划出来，赋予特别的神圣地位。','后期拉丁 sanctificare，含 sanctus 神圣 + facere 使、做；经法语借入，后来调整拼写。',SANCTIFY,'sanctify a place 是使某地成为圣地；比喻中也可说某种传统或话语给行为罩上神圣、正当的外衣。后者可能带批评意味。','sanctify a place；sanctify a practice；sanctified by tradition。','sanction 侧重正式批准，sanctify 侧重赋予神圣性；普通审批通常不用 sanctify。',('The ritual was performed to sanctify the new chapel.','举行这项仪式是为了给新礼拜堂祝圣。'),('Age alone does not sanctify an unjust custom.','一项习俗再古老，也不能因此让不公变得正当。'),sources=['https://www.etymonline.com/word/sanctify','https://www.oxfordlearnersdictionaries.com/definition/english/sanctify']),
E('sanctification','/ˌsæŋktɪfɪˈkeɪʃən/','成圣；使神圣的过程或状态','关注一个人或某件事被赋予神圣地位、变得圣洁的过程。','古法语 sanctificacion、教会拉丁 sanctificatio 借入；与 sanctify 同源，现代 -ify / -ification 相配不等于名词只在英语里形成。',SAN+[['后期拉丁 sanctificare → 教会拉丁 sanctificatio；古法语 sanctificacion','使神圣 → 成圣、使神圣的过程'],['英语 sanctification','宗教中的成圣；也可比喻把某物奉为神圣']],'宗教文章里的 sanctification 常有特定神学含义，不同传统解释未必一致。比喻的 sanctification of a leader 则可能批评把领导者抬到不容质疑的位置。','the process of sanctification；a doctrine of sanctification；the sanctification of。','sanctity 是神圣的性质；sanctification 关注变得或被看作神圣的过程。',('The chapter compares different understandings of sanctification.','这一章比较了对成圣的不同理解。'),('The critic warned against the sanctification of political leaders.','评论者警告不要把政治领导人神圣化。'),sources=['https://www.etymonline.com/word/sanctification','https://www.oxfordlearnersdictionaries.com/definition/english/sanctification']),
E('sanctimonious','英 /ˌsæŋktɪˈməʊniəs/；美 /ˌsæŋktɪˈmoʊniəs/','假正经的；自命清高的；道貌岸然的','把自己摆在道德高处，居高临下地教训别人。','sanctimony + -ous；sanctimony 经法语 sanctimonie 接拉丁 sanctimonia 神圣。英语形容词很早已有讽刺义，不能硬说先长期只褒义才转贬义。',SAN+[['拉丁 sanctimonia → 法语 sanctimonie → 英语 sanctimony','圣洁、虔敬；后来也指装出来的虔敬'],['英语 sanctimony + -ous → sanctimonious','早期已有装圣洁的讽刺用法；现代通常批评道德优越姿态']],'a sanctimonious lecture 是一通自以为站在道德高处的说教；a sanctimonious tone 让人觉得说话者在炫耀自己有多正派。并不专指宗教人士。','a sanctimonious tone；sanctimonious lectures；sound sanctimonious。','saintly 赞善良，sanctimonious 批评装得高尚；sincere 则强调真诚。',('His sanctimonious tone made the apology sound insincere.','他那副自命清高的语气，让道歉显得不真诚。'),('She was tired of sanctimonious lectures about how others should live.','她厌烦了那些教别人该怎样生活的道德说教。'),sources=['https://www.etymonline.com/word/sanctimonious','https://en.wiktionary.org/wiki/sanctimonious#English','https://www.oxfordlearnersdictionaries.com/definition/english/sanctimonious']),
]
