CL=[['拉丁 -clinare','弯、倾斜；与希腊 klinein 倾斜、躺卧同源，并非后者的直接后代']]
INCL=CL+[['拉丁 in- + clinare → inclinare → 古法语 encliner → 英语 incline','向某个方向倾斜 → 身体倾斜、意向偏向']]
INCLINATION=CL+[['拉丁 inclinare → inclinatio；古法语 inclination → 英语 inclination','倾斜 → 倾向；倾斜角度']]
RECL=CL+[['拉丁 re- + clinare → reclinare；古法语 recliner → 英语 recline','往后倾 → 后仰、斜躺']]
DECL=CL+[['拉丁 de- + clinare → declinare → 古法语 decliner → 英语 decline','偏离、下斜 → 下降、衰退；转开 → 婉拒']]
W += [
E('incline','动词 /ɪnˈklaɪn/；名词 /ˈɪnklaɪn/','倾斜；倾向；使倾向；斜坡','身体朝一边偏，心里的选择也朝某个方向偏。','拉丁 in- 向 + clinare 倾斜，经过法语 encliner；英语后来由动词发展出名词斜坡。',INCL+[['英语 incline〔名词〕','倾斜状态、倾向；后来常指斜坡']],'incline your head 是低头或偏头；incline to agree 是倾向同意。a steep incline 是陡坡，此时重音在开头。','incline towards；incline to agree；a gentle/steep incline。','lean 更日常，也可说身体或观点倾向；incline 较正式，名词用来描述坡道。',('The path rises along a gentle incline.','小路沿着一道缓坡上升。'),('The new evidence inclines me to agree with her.','新证据让我更倾向于同意她。'),('He inclined his head in greeting.','他略微低头致意。'),sources=['https://www.etymonline.com/word/incline','https://www.oxfordlearnersdictionaries.com/definition/english/incline_1','https://www.oxfordlearnersdictionaries.com/definition/english/incline_2']),
E('inclined','/ɪnˈklaɪnd/','倾向于的；愿意的；有某方面才能的；倾斜的','可以是身体有坡度，也可以是心或才能自然偏向某一面。','incline + -ed，过去分词作形容词；心里偏向的比喻很早就有。',INCL+[['英语 incline + -ed → inclined','倾斜的；心理倾向、能力倾向']],'be inclined to do 可以是想做，也可表示容易做；musically inclined 是有音乐兴趣或才能。an inclined plane 则是物理上的斜面。','be inclined to agree；musically inclined；an inclined plane。','willing 强调愿意；inclined 常只是偏向、倾向，不一定已决定行动。',('I am inclined to accept the offer, but I need another day to decide.','我倾向接受这个提议，但还需要一天来决定。'),('The cart rolled down the inclined surface.','小车沿倾斜的表面滑了下去。'),sources=['https://www.etymonline.com/word/inclined','https://en.wiktionary.org/wiki/inclined#English']),
E('inclination','/ˌɪnklɪˈneɪʃən/','倾向；意愿；斜度；倾角','把朝某方向偏的状态拿出来说，可以是想法，也可以是几何角度。','拉丁 inclinatio 经法语或直接借入；与 incline 同源，但不是现代英语动词机械加 -ation 才有的词。',INCLINATION,'have no inclination to argue 是一点也不想争论；an angle of inclination 是倾角。by inclination 可以说明出于个人爱好、性情。','an inclination to do；by inclination；the angle of inclination。','intention 是行动意图，通常更接近计划；inclination 可以仅仅是偏好，还没打算去做。',('She had little inclination to discuss work during the holiday.','假期里，她不大想讨论工作。'),('The diagram shows the roof’s angle of inclination.','示意图标出了屋顶的倾角。'),sources=['https://www.etymonline.com/word/inclination','https://www.oxfordlearnersdictionaries.com/definition/english/inclination']),
E('disinclined','/ˌdɪsɪnˈklaɪnd/','不愿意的；不大想的','心里的箭头没有指向这件事，甚至有点往外躲。','dis- 否定 + inclined；表示没有相应意愿，不是身体反方向倾斜。',INCL+[['英语 inclined；dis- + inclined → disinclined','有意愿、倾向 → 不愿、不倾向']],'be disinclined to discuss 是不太愿意讨论，常见于较正式表达。I am disinclined to agree 比直接否定稍绕一些，但不代表中立。','disinclined to do；feel disinclined；rather disinclined。','unable 是做不到；disinclined 是不想做，能力与意愿不同。',('After the long journey, we were disinclined to go out again.','长途旅行之后，我们不大想再出门。'),('She seemed disinclined to offer further details.','她似乎不愿再提供更多细节。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/disinclined','https://en.wiktionary.org/wiki/disinclined#English']),
E('disinclination','/ˌdɪsˌɪnklɪˈneɪʃən/','不愿意；缺少兴趣或倾向','把那种不想投入、不愿靠近的心情作为一个名词来讲。','dis- 不 + inclination 倾向；英语内部形成的否定名词。',INCLINATION+[['英语 dis- + inclination → disinclination','倾向、意愿 → 缺少意愿']],'a disinclination to travel 是不想出行；disinclination for exercise 是不爱运动。这类说法较正式，日常常直接说 do not feel like。','a disinclination to do；disinclination for；overcome a disinclination。','inability 是没有能力；disinclination 是缺少意愿。reluctance 还常暗示虽不情愿但可能最终会做。',('His disinclination to ask for help made the task harder.','他不愿求助，这让任务更难完成。'),('She admitted a general disinclination for large social gatherings.','她承认自己总体上不喜欢大型社交聚会。'),sources=['https://www.etymonline.com/word/disinclination','https://www.oxfordlearnersdictionaries.com/definition/english/disinclination']),
E('recline','/rɪˈklaɪn/','后仰；斜躺；使座椅后倾','把身体的重量往后放，不再笔直坐着。','拉丁 re- 向后 + clinare，形成 reclinare；经法语或直接借入。这里 re- 不是再躺一次。',RECL,'recline on a sofa 是斜躺在沙发上；recline a seat 是把椅背向后放。可以说人改变姿势，也可以说调节椅子。','recline on；recline in a chair；recline the seat。','lean back 只是向后靠；recline 常暗示更放松、更接近躺卧，但不一定完全躺平。',('She reclined on the sofa with a book.','她拿着一本书斜躺在沙发上。'),('Press this button to recline the seat.','按这个按钮可以把座椅靠背向后放。'),sources=['https://www.etymonline.com/word/recline','https://www.oxfordlearnersdictionaries.com/definition/english/recline']),
E('recliner','英 /rɪˈklaɪnə/；美 /rɪˈklaɪnər/','可后仰的躺椅','椅背可以往后放，让坐姿慢慢变成半躺姿势的椅子。','recline + -er；原可指后仰的人或物，后来常专指这种座椅。',RECL+[['英语 recline + -er → recliner','后仰者、后仰装置 → 可调后仰座椅']],'a leather recliner 是皮面躺椅；通常是有靠背调节机构的舒适座椅，有些还带脚托。-er 在这里不主要指一个人。','sit in a recliner；a reclining chair；a leather recliner。','armchair 是扶手椅，不一定能后仰；recliner 的关键是能让人靠后躺下。',('He fell asleep in the recliner by the window.','他在窗边的躺椅上睡着了。'),('The recliner has an adjustable back and a footrest.','这把躺椅有可调节的靠背和脚托。'),sources=['https://www.etymonline.com/word/recliner','https://www.oxfordlearnersdictionaries.com/definition/english/recliner']),
E('reclining','/rɪˈklaɪnɪŋ/','斜躺的；可后仰的；正在后仰','描述人的姿势，或说明椅子能让人后仰。','recline + -ing，去词尾 e；分词也能作形容词。',RECL+[['英语 recline + -ing → reclining','斜躺、后仰 → 处于该姿势的；可使人后仰的']],'a reclining figure 是斜躺的人像；a reclining seat 是可后仰座椅。后者说明功能，不是椅子自己正在躺下。','a reclining figure；a reclining seat；a reclining position。','recliner 是椅子名词；reclining 修饰人、姿势或座椅，不只限一种家具。',('The painting shows a reclining figure beside a window.','这幅画描绘了窗旁一个斜躺的人。'),('The coach has reclining seats for overnight journeys.','这辆长途客车配有可后仰座椅，方便夜间出行。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/recline','https://en.wiktionary.org/wiki/reclining#English']),
E('declining','/dɪˈklaɪnɪŋ/','下降的；衰退的；正在婉拒','走势往下，或人在把某个邀请、提议轻轻推开。','decline + -ing，去词尾 e；保留 decline 的下降与拒绝两种主要动作。',DECL+[['英语 decline + -ing → declining','下降、婉拒 → 持续下降的、正在婉拒']],'declining sales 是销售额下降；declining an invitation 是谢绝邀请。看到 declining 后面是数字指标还是具体提议，往往就能分清。','declining sales；a declining industry；declining an invitation。','declining 说明正在下降；low 只说明当前水平低，未必还在往下走。',('The town is trying to revive its declining fishing industry.','这座城镇正努力振兴日渐衰退的渔业。'),('She felt awkward about declining another invitation.','再次谢绝邀请让她有些不好意思。'),sources=['https://www.etymonline.com/word/decline','https://en.wiktionary.org/wiki/declining#English']),
E('declination','/ˌdeklɪˈneɪʃən/','赤纬；磁偏角；倾斜、偏离','在专业语境里，把偏离某条基准的角度量出来。','拉丁 declinatio 经法语或直接借入，接 declinare 偏开；不只是在英语 decline 后临时加名词词尾。',CL+[['拉丁 declinare → declinatio；古法语 declinacion → 英语 declination','偏转、倾斜 → 天文学等领域的角度名称']],'天文学中的 declination 是赤纬，表示天体在天赤道以北或以南多少度；magnetic declination 是当地磁北方向相对真北的水平夹角。这两个角的基准不同。','magnetic declination；right ascension and declination；a declination angle。','magnetic inclination 是磁倾角，量磁场与水平面的夹角；magnetic declination 是磁偏角，量水平方向的偏差。',('The star chart lists right ascension and declination.','星图列出了赤经和赤纬。'),('Magnetic declination varies with location and changes over time.','磁偏角随地点不同而变化，也会随时间改变。'),sources=['https://www.etymonline.com/word/declination','https://en.wiktionary.org/wiki/declination#English','https://www.ncei.noaa.gov/products/magnetic-declination','https://www.ncei.noaa.gov/products/geomagnetism-frequently-asked-questions','https://science.nasa.gov/learn/basics-of-space-flight/chapter2-2/']),
E('inch','/ɪntʃ/','英寸；一点点；缓慢挪动','一英尺切成十二份，每一份就是一英寸；由小单位引申为一点点地移动。','拉丁 uncia 十二分之一，早期借入古英语 ynce，经中古英语成为 inch；与后经法语进入的 ounce 同源。',[['拉丁 uncia → 古英语 ynce → 中古英语 ynche / unche → inch','十二分之一 → 英尺的十二分之一'],['英语 inch〔动词〕','小长度单位 → 一点点挪动']],'一英寸等于 2.54 厘米，常缩写 in。inch forward 是缓慢往前挪。少见的苏格兰地名 inch 小岛来自盖尔语 innis，与长度单位另源。','an inch of rain；inch by inch；inch forward；every inch。','inch 是长度；ounce 常是质量单位。every inch of the room 强调每一寸地方，不是要求逐寸测量。',('Leave an inch of space between the frame and the shelf.','在框架与架子之间留出一英寸空隙。'),('The queue inched forward as more counters opened.','随着更多柜台开放，队伍一点点向前移动。'),sources=['https://www.etymonline.com/word/inch','https://en.wiktionary.org/wiki/inch#English','https://www.nist.gov/pml/special-publication-811/nist-guide-si-appendix-b-conversion-factors/nist-guide-si-appendix-b8']),
E('ounce','/aʊns/','盎司；少量、一点点','原本是分出来的一小份，今天既是计量单位，也能强调一点点都没有。','拉丁 uncia 十二分之一，经法语 once / unce 进入英语；并非从英语 inch 变来，两词是不同时间借入的同源词。',[['拉丁 uncia → 古法语 once / unce → 英语 ounce','十二分之一 → 质量计量单位'],['英语 ounce 的比喻用法','小单位 → 很少量、一点点']],'常用的常衡盎司约 28.35 克，是常衡磅的十六分之一；金衡盎司属于另一套单位。fluid ounce 是容量，不能直接等同重量。not an ounce of patience 是一点耐心也没有。','an ounce of；not an ounce of；ounces of flour；fluid ounce。','词源中的十二分之一不能硬套现代所有制度。另有罕见 ounce 雪豹义，源于表示猞猁的旧法语词，与 uncia 无关。',('The recipe calls for two ounces of butter.','食谱要求两盎司黄油。'),('There was not an ounce of truth in the rumour.','那个传闻没有一点真实性。'),sources=['https://www.etymonline.com/word/ounce','https://en.wiktionary.org/wiki/ounce#English','https://www.nist.gov/pml/owm/metric-si/unit-conversion/approximate-conversions-us-customary-measures-metric']),
]
