DEFERRED={'integrable':'数学专门性质，当前先保留基础积分词汇。','integrational':'少用派生形容词，优先 integration 与 integrative。','stereoscopy':'体视技术的专门名词，先讲较常见 stereoscopic。','periscopic':'较少用仪器形容词，已有 periscope 逐词讲解。','diascopic':'较冷门光学、检查术语，暂略。','diascopy':'较专门医学或投影检查术语，暂略。','epidiascope':'较少见投影设备名称，暂略。','episcope':'专门设备或古旧称谓，暂略。','episcopic':'专门或古旧形容词，暂略。','panendoscopy':'较专门的内镜检查术语，暂略。','scopophobia':'较冷门恐惧症名称，暂略。','Telescopium':'星座专名，暂不列通用词族。','Abroscopus':'鸟类属名，暂不列通用词族。','uncial':'古文字学、书法专门词，按用户偏好暂略。','quincuncial':'排列与植物学的冷门术语，暂略。','semiuncial':'古文字学专门术语，暂略。'}
INTEGR_ROOT=dict(id='C0608',meaning='完整、未受损；整合、整体与正直',core='想象一件东西保持完整：数字可以没有零碎部分，系统可以各部分连成一体，人也可以守住不被利益破坏的原则。',image='拉丁 integer 完整 → integer 整数；经法语 entier → entire 整个；integrare 使完整 → integrate；integritas 完整、正直 → integrity 与 entirety 两条借入线。',intro='integr- 并不是独立的英语动词。它的核心来自拉丁 integer，历史上与否定 in- 和触碰的词根相连：没有被碰坏、完整。integrate、integration、integral、integrity 各有借入路线，不能都说成英语 integrate 换词尾。',forms='integer 中 g 读 /dʒ/，integrate、integrity 中 g 读 /ɡ/。integral、integrally 常见两种重音。entire 与 integer 是同源的不同借入形式，entirety 与 integrity 也有相应关系。',branches=[['形成整体','integrate, integration, integrated, integrative, integrator'],['整体中不可少的部分','integral, integrally'],['整数、完整与正直','integer, integrity'],['整个、完全、全部','entire, entirely, entirety'],['散开、重新接回、尚未接通','disintegrate, disintegration, reintegrate, reintegration, unintegrated']],contrasts='integration 是整合过程，integrity 是完整性或操守；integral 是不可分割的重要部分，integrated 是已经整合；integer 包括负整数和零，并非只指正数。',practice='用 integration 与 integrity 各写一个数据场景；比较 an integral part 与 an integrated system；说明为什么 integer 与 entire 拼写很不同仍是同源。',words=[w for w in ASSIGN['roots'][90]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][90]['family'] if w in DEFERRED})
SCOP_ROOT=dict(id='C1276',meaning='观察、审视；观察工具与怀疑态度',core='把目光放到对象上，仔细看清；往思想里走，就是先审视证据，再决定信不信。',image='希腊 skopein / skopos 观察、目标 → scope；micro- 小 + -scope → microscope；endo- 内 + -scopy → endoscopy；skeptesthai 审视 → skeptikos → skeptic。',intro='scop- 与 scept- / skept- 是同源形态，不是现代单词任意换字母。观察镜中的 -scope 常指工具，-scopy 常指过程。scope 的范围义经意大利语等语言而来，仪器义是 telescope、microscope 等的截短；两支分开读更清楚。',forms='skeptic/skeptical/skepticism 在英式常写 sceptic/sceptical/scepticism，开头仍读 /sk/。microscope 变 microscopic、microscopically 时重音移到 -scop-。stethoscope 的观察是检查之意，实际主要靠听。',branches=[['范围与观察','scope'],['小、远、较大尺度','microscope, microscopic, microscopically, macroscopic, telescope, telescopic, periscope'],['先审视再相信','skeptic, skepticism, skeptical, skeptically'],['多变图案与立体视觉','kaleidoscope, kaleidoscopic, stereoscopic'],['身体内部与声音','endoscope, endoscopy, endoscopic, gastroscopy, stethoscope']],contrasts='skeptic 质疑说法，cynic 常质疑动机；endoscope 是设备，endoscopy 是检查；telescopic 既能说望远镜相关，也能说套管式伸缩。microscopic 不一定在每个夸张句里都真的肉眼不可见。',practice='比较 scope of the project 与 scope for improvement；把 endoscope、endoscopy、endoscopic 放入同一次检查的描述；解释听诊器为何可以有 -scope。',words=[w for w in ASSIGN['roots'][91]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][91]['family'])+['Telescopium','Abroscopus'] if w in DEFERRED})
SANC_ROOT=dict(id='C1254',meaning='使神圣、确认、制定；保护与认可',core='把某件事划出来，赋予它特别地位：可以神圣不可侵犯，也可以由权威确认、保护或强制执行。',image='拉丁 sancire → sanctus → saint；sanctuarium 圣所 → sanctuary 庇护处；sanctio 规定 → sanction 批准／处罚；sanctificare → sanctify。',intro='这一组不只有宗教义。sanctuary 可以是动物保护区，sacrosanct 可以说不可改变的习惯，sanction 可以批准或制裁。共同线索是特别的地位和权威，但具体意思必须看每个词的发展。sanct- 的神圣与 san- 的健康不同。',forms='saint 经法语发生明显词形变化，不能按现代拼写看出 sanctus 的每个字母。sanctify / sanctification 是动词与名词对应，但名词有独立的法语、拉丁借入路线。sanctioned 的两种方向不能只靠 -ed 判断。',branches=[['人、品格与神圣性','saint, saintly, sanctity'],['保护和不可侵犯','sanctuary, sacrosanct'],['权威的批准与惩处','sanction, sanctioned, unsanctioned'],['使神圣与装作高尚','sanctify, sanctification, sanctimonious']],contrasts='saintly 多为赞扬，sanctimonious 通常批评自命清高；sanction 批准不等于 sanctify 使神圣；sanctity 与 sanity 的神志清醒义不同。',practice='各用一句话表达 sanction 的批准义和处罚义；比较圣人般的耐心与道德优越的语气；用 sanctuary 描写一个日常安静避所。',words=list(ASSIGN['roots'][92]['family']),exclude={})
CLIN_ROOT=dict(id='C0238',meaning='弯、倾斜、躺卧；倾向、下降与拒绝',core='身体可以往前后倾，心里的意愿也可以向某个选择偏；向下或转开的动作又能发展成衰退、婉拒。',image='拉丁 clinare 倾斜 → inclinare 向某方倾 → incline；reclinare 后仰 → recline；declinare 偏开、下斜 → decline。希腊同源 klinein／kline 床另生 clinic 一支。',intro='clin- 在本页以拉丁 -clinare 为主。clinic、clinical、clinically、preclinical 属相关的希腊 kline 床一支，作为同源旁支复用，不画成拉丁 incline 的后代。decline 下降与婉拒可以借向下、转开两个画面区分。',forms='incline 作动词重读后半，作斜坡名词重读前半。inclination 与 declination 都有拉丁、法语名词的独立历史。recline 的 re- 是向后，不是重复一次。',branches=[['朝一边倾、心里偏向','incline, inclined, inclination'],['没有这种意愿','disinclined, disinclination'],['后仰与家具','recline, recliner, reclining'],['下降、偏转与拒绝','decline, declining, declination'],['希腊同源的床与临床支线〔共享〕','clinic, clinical, clinically, preclinical']],contrasts='inclined 是倾向，disinclined 是不愿；recliner 是可后仰椅，reclining 是姿势或功能形容。磁偏角 declination 量水平方向偏差，磁倾角 inclination 量磁场与水平面的夹角。',practice='读出 incline 的名词、动词不同重音；分别描述愿意做事、斜躺休息、销售下降；解释 clinic 不能拆成现代 incline 的缩写。',words=list(dict.fromkeys(list(ASSIGN['roots'][93]['family'])+['clinic','clinical','clinically','preclinical'])),exclude={})
UNCI_ROOT=dict(id='C1582',meaning='十二分之一；英寸与盎司的共同来源',core='把一个单位切成十二份，取其中一份；两个常见英语单位从这同一古代词出发，后来走上不同道路。',image='拉丁 uncia 十二分之一 → 古英语 ynce → inch；另经古法语 once → ounce。',intro='inch 和 ounce 并非一个从另一个变来：inch 较早直接借入古英语，ounce 后来经法语传入。历史上的十二分之一解释命名来源，却不能代替今天的单位定义；常衡盎司是一常衡磅的十六分之一。',forms='inch 读 /ɪntʃ/，复数 inches；ounce 读 /aʊns/，复数 ounces。inch 可作慢慢挪动的动词；ounce 也可表示少量。fluid ounce 是容量单位。',branches=[['长度、小步移动','inch'],['质量、一点点','ounce']],contrasts='inch 是长度，ounce 通常是质量；fluid ounce 是容量。苏格兰小岛义 inch、雪豹义 ounce 是同形异源词，不接到 uncia。',practice='用 inch 既写一个长度，也写一个缓慢动作；解释 not an ounce of truth；说明为什么不能只靠十二分之一换算现代常衡盎司。',words=[w for w in ASSIGN['roots'][94]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][94]['family'])+['semiuncial'] if w in DEFERRED})
